ALTER TABLE TRADE.EXECUTION_EVENT ADD COLUMN IF NOT EXISTS TRANSACT_AT TIMESTAMPTZ;

UPDATE TRADE.EXECUTION_EVENT
   SET TRANSACT_AT = CREATED_AT
 WHERE TRANSACT_AT IS NULL;

ALTER TABLE TRADE.EXECUTION_EVENT
    ALTER COLUMN TRANSACT_AT SET NOT NULL;

